package com.collegeerp.erp.account.controller; import com.collegeerp.erp.account.dto.AccountDtos.*; import com.collegeerp.erp.account.service.AccountService; import com.collegeerp.erp.common.api.ApiResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/account") public class AccountController{private final AccountService service;public AccountController(AccountService s){service=s;}@GetMapping("/me")public ApiResponse<?>me(){return ApiResponse.success("Account profile",service.me());}@PutMapping("/me")public ApiResponse<?>update(@Valid@RequestBody UpdateProfile r){return ApiResponse.success("Profile updated",service.update(r));}@PatchMapping("/change-password")public ApiResponse<?>change(@Valid@RequestBody ChangePassword r){service.change(r);return ApiResponse.success("Password changed successfully",null);}}
